-- Original project-owned CEFR practice catalog. Idempotent and safe for local development.
BEGIN;
WITH topic_content(slug,titles,prompts) AS (VALUES
('daily-life',ARRAY['My morning routine','A busy weekday','A change to my routine','Balancing work and free time','The social value of daily routines'],ARRAY['Write three sentences about what you do before breakfast.','Describe a typical weekday and explain which part you enjoy most.','Explain how your routine changed recently and why.','Argue for two ways people can create a healthier work-life balance.','Critically examine how modern routines influence personal identity and community life.']),
('family-friends',ARRAY['A person in my family','Planning time with friends','A friendship that taught me something','Maintaining friendships online','Individual choice and family obligation'],ARRAY['Introduce one family member using simple sentences.','Write a short paragraph inviting friends to spend an afternoon together.','Describe a friendship experience and explain what you learned.','Discuss whether social media strengthens or weakens close friendships.','Evaluate the tension between individual autonomy and family responsibility across cultures.']),
('school-education',ARRAY['My classroom','A useful school club','Advice for a new student','Should homework be reduced?','Assessing equal access to education'],ARRAY['Describe your classroom and name two things in it.','Explain which school club you would join and why.','Write an email giving a new student practical study advice.','Present a balanced argument about reducing homework for secondary students.','Critically analyze one policy that could reduce inequality in access to education.']),
('work-career',ARRAY['A job I know','My future job','A workplace problem','Remote work and productivity','The changing meaning of professional expertise'],ARRAY['Write simple sentences about a job and its daily tasks.','Describe a job you would like and the skills it needs.','Write a professional email explaining a small workplace problem and proposing a solution.','Discuss the advantages and disadvantages of remote work for productivity.','Evaluate how automation is changing the value of human expertise in professional life.']),
('travel-culture',ARRAY['A place I want to visit','A weekend trip','A cultural surprise','Responsible tourism','Tourism, authenticity, and cultural ownership'],ARRAY['Write three sentences about a place you want to visit.','Describe a weekend trip, including transport, activities, and one recommendation.','Tell a friend about a cultural difference you noticed while travelling.','Argue for practical ways tourists can reduce harm to local communities.','Critically discuss whether tourism preserves culture or turns it into a commercial product.']),
('technology',ARRAY['A device I use','Technology in my day','Solving a problem with technology','Should phones be restricted in class?','Digital convenience and human agency'],ARRAY['Name a device you use and write what you do with it.','Explain how one app helps you in daily life and mention one limitation.','Describe a time technology solved a problem for you.','Present both sides of restricting smartphones in classrooms and state your position.','Analyze how algorithmic convenience may influence individual choice and responsibility.']),
('health-lifestyle',ARRAY['A healthy meal','A healthy weekly habit','Encouraging a friend to exercise','Who is responsible for public health?','Wellbeing as an individual and political concept'],ARRAY['Write three sentences about a healthy meal you like.','Describe one healthy habit and explain how you maintain it each week.','Write an informal email encouraging a friend to begin a realistic exercise routine.','Discuss whether governments or individuals should carry more responsibility for public health.','Critically evaluate how economic conditions shape common definitions of personal wellbeing.']),
('business-english',ARRAY['A local shop','A simple customer request','Following up after a meeting','Transparent communication during change','Ethical persuasion in corporate communication'],ARRAY['Write three sentences describing a shop in your area.','Write a short message asking a business for product information.','Write a professional follow-up email that confirms actions after a meeting.','Argue for a communication plan when a company makes a difficult organizational change.','Analyze the ethical boundary between persuasive business communication and manipulation.']),
('email-writing',ARRAY['A friendly invitation','Asking for course information','Apologizing for a delayed reply','Requesting a formal review','Writing with authority and restraint'],ARRAY['Write a short email inviting a friend to your home.','Write an email asking about the schedule and price of an English course.','Write an email apologizing for a late response and proposing the next step.','Write a formal email requesting that an organization review an unfair decision.','Write a concise executive email that challenges a proposal while preserving professional trust.']),
('ielts-writing',ARRAY['Comparing two everyday choices','Giving a clear opinion','Explaining causes and solutions','Advantages and disadvantages essay','Critical response to a complex claim'],ARRAY['Write simple sentences comparing studying at home and studying in class.','Write a short opinion paragraph about learning English online.','Explain causes of traffic congestion and suggest practical solutions.','Write a structured essay discussing advantages and disadvantages of working from home.','Write a nuanced essay evaluating whether economic growth should remain the primary measure of national success.'])
), levels(level,position,min_words,recommended_words,minutes,difficulty) AS (VALUES
('A1',1,15,35,8,1),('A2',2,40,70,12,2),('B1',3,80,120,20,3),('B2',4,140,200,30,4),('C1',5,220,300,45,5)
), expanded AS (
 SELECT t.slug,l.level,l.position,t.titles[l.position] title,t.prompts[l.position] prompt,l.min_words,l.recommended_words,l.minutes,l.difficulty,
   CASE WHEN l.level='A1' THEN 'sentence' WHEN l.level='A2' THEN 'paragraph'
     WHEN l.level='B1' AND t.slug IN ('work-career','health-lifestyle','business-english','email-writing') THEN 'email'
     WHEN l.level='B1' THEN 'paragraph' WHEN l.level='B2' AND t.slug='email-writing' THEN 'email'
     WHEN l.level='B2' THEN 'opinion' ELSE 'essay' END kind
 FROM topic_content t CROSS JOIN levels l
)
INSERT INTO public.writing_exercises(id,slug,topic_id,cefr_level,kind,title,prompt,instructions,hint,tokens,
  min_words,recommended_words,estimated_minutes,difficulty,is_published)
SELECT (md5('writing-v22:'||e.slug||':'||e.level))::uuid,e.slug||'-'||lower(e.level),t.id,e.level,e.kind,e.title,e.prompt,
  'Organize your ideas before writing. Use language appropriate for '||e.level||'.',
  CASE WHEN e.level IN ('A1','A2') THEN 'Use clear sentences and check basic punctuation.' ELSE 'Support each main idea with a reason or example.' END,
  '[]'::jsonb,e.min_words,e.recommended_words,e.minutes,e.difficulty,true
FROM expanded e JOIN public.writing_topics t ON t.slug=e.slug
ON CONFLICT(slug) DO NOTHING;
COMMIT;
